local config = {
  ui_story_5084_50840100_1_dialog_content = "นี่คือ... หลุมฝังศพ?",
  ui_story_5084_50840100_2_dialog_content = "\"Varaki, ชะตากรรมของคุณถูกเปิดเผยแล้ว แต่หัวใจของคุณยังคงมีความสงสัย\"",
  ui_story_5084_50840100_3_dialog_content = "เพราะฉันเข้าใจราคาที่ต้องจ่าย การได้มาซึ่งพลังคือการกลายเป็นนักโทษของมัน และสละความสงบสุขไปในชีวิตทั้งหมด",
  ui_story_5084_50840100_4_dialog_content = "ฉันไม่ต้องการเป็นเหมือนพ่อแม่ของฉันและต้องทนทุกข์เพราะความแข็งแกร่งของฉัน พวกเขาจึงพบความสงบเมื่อน้ำตาล Varaki ในร่างกายของพวกเขาหมดสุดท้าย.",
