  ui_story_5084_50840100_6_dialog_content = "\"ในฐานะศิษย์ของสัจจธรรม คุณได้ท่องทางไปในโลกนี้และค้นพบพลังที่ยิ่งใหญ่\"",
  ui_story_5084_50840100_7_dialog_content = "\"ถ้าหัวใจของคุณตั้งใจอยากให้เจ้าแห่งความจริงมาถึง คุณก็ไม่มีเหตุผลที่จะกลัวการสละสิ่งใดๆ\"",
