  ui_story_5084_50840201_45_dialog_content = "<color=#e8d9bb>อย่างช้า ๆ และสำคัญ ๆ พวกเขาเดินผ่านทุกถนนในเมืองก่อนที่จะถึงประตูของวัดแห่งความจริง</color>",
