  ui_story_5084_50840301_55_dialog_content = "(ฉันรับรู้ถึงอันตรายร้ายแรงที่กำลังมาจากหัวหน้าครอบครัวเหล่านี้...)",
  ui_story_5084_50840301_56_dialog_content = "(จะเกิดอะไรขึ้นหากวิกตอเรียถูกสังหารจริง ๆ ?!)",
  ui_story_5084_50840301_57_dialog_content = "(ไม่ได้เลย, ฉันต้องทำอะไรสักอย่างก่อนที่วิกตอเรียจะเข้าไปในโลงนั้น...)",
  ui_story_5084_50840301_58_option_content = "ลิงค์โทรจิต",
  ui_story_5084_50840301_59_dialog_content = "คุณในที่สุดก็ตามทัน",
  ui_story_5084_50840301_60_dialog_content = "มันดูไม่ถูกต้องที่นี่นะ วิกตอเรีย... คุณจะยอมให้หนุ่มคนนี้ใส่คุณลงในโลงศพแล้วบูชาคุณจริงๆหรือ?!",
  ui_story_5084_50840301_61_dialog_content = "ได้สิ",
  ui_story_5084_50840301_62_dialog_content = "ธ-ถ้างั้น... เมย์กับผมควรทำอย่างไรดี?!",
  ui_story_5084_50840301_63_dialog_content = "คุณจำคำพูดของซิคาเรได้ไหม?",
  ui_story_5084_50840301_64_dialog_content = "แน่นอนว่าฉันทำ! \"ชะตากรรมถูกกำหนดไว้นานแล้ว ไม่มีการสงสัย ความรู้สึกไม่พอใจ หรือการเปลี่ยนแปลงมัน\"",
  ui_story_5084_50840301_65_dialog_content = "ไม่ต้องสงสัยอะไรเลย...",
