  ui_story_5084_50840301_87_dialog_content = "ไม่ต้องห่วงเมย์! ฉันอยู่ตรงนี้นะ!",
  ui_story_5084_50840301_88_dialog_content = "หา...?!",
  ui_story_5084_50840301_89_dialog_content = "ดูเหมือนว่าลมดำที่พัดมาเมื่อกี้ได้ดับเทียนของฉัน... ฉันมองไม่เห็นอะไรในที่นี้เลย!",
