  ui_story_5084_50840301_91_dialog_content = "ยังไม่รวมถึงทุกสิ่งที่คนชื่อวิลเฮล์มพูดเกี่ยวกับวิกตอเรีย...",
  ui_story_5084_50840301_92_dialog_content = "เธอไม่ได้อยู่ในอันตรายใช่มั้ย? ไม่... ฉันต้องรู้ว่าพวกเขาหัวเราะเรื่องอะไรกัน!",
  ui_story_5084_50840301_93_option_content = "บังคับเชื่อมกระแสจิต—",
  ui_story_5084_50840301_94_dialog_content = "(ฉัน... ฉันแทบจะมองอะไรไม่เห็นเลย... เกิดอะไรขึ้นที่นี่...?)",
