  ui_story_5084_50840301_96_dialog_content = "คุณรู้ดีว่าการเข้าไปในโลงศพนั้นหมายถึงอะไรสำหรับคนหนึ่ง แน่นอนว่าคุณมีเจตนาลับในการเลือกลูกสาวของ<color=#FFB400>ออสเตน วารากิ</color>ใช่มั้ย?",
  ui_story_5084_50840301_97_dialog_content = "เขาเป็นผู้นำก่อนหน้าของ True Order และเป็นพี่ชายของฉัน ด้วยธรรมชาติ การดูแลลูกสาวที่เขารักนั้นเป็นหน้าที่ของฉัน",
  ui_story_5084_50840301_98_dialog_content = "(เดี๋ยวนะ, วิลเฮล์ม... เป็นคุณลุงของวิกตอเรียเหรอ?)",
  ui_story_5084_50840301_99_dialog_content = "ฉันเบื่อคำพูดที่หยิ่งยโสของเจ้าแล้ว วาราคี",
  ui_story_5084_50840301_100_dialog_content = "ฉันรู้ดีว่าคุณยังหาวิธีแก้ปัญหาไม่ได้เลย",
  ui_story_5084_50840301_101_dialog_content = "ถ้าคุณจริงจังที่จะให้ความสนใจที่ดีที่สุดกับเธอ ทำไมคุณไม่ไปร่วมกับเธอที่นั่น...?",
  ui_story_5084_50840301_102_dialog_content = "เดี๋ยวนะ—",
  ui_story_5084_50840301_103_dialog_content = "คุณคิดว่าคุณกำลังทำอะไรอยู่วิลเฮล์ม? นี่ไม่เหมือนกับที่คุณบอกมาเลย.",
