  ui_story_5084_50840301_106_dialog_content = "<color=#e8d9bb>Pshhhh—Pshhhh—!!</color>",
  ui_story_5084_50840301_107_dialog_content = "(ไม่นะ... ดูเหมือนว่าลมสีดำนี้มันถูกสร้างขึ้นมาเพื่อซ่อนทุกอย่างจากตอนแรกเลย...)",
  ui_story_5084_50840301_108_dialog_content = "(Clavis, Wilhelm, และวิกตอเรีย... พวกเขากำลังวางแผนอะไรกันเนี่ย?)",
  ui_story_5084_50840301_109_dialog_content = "อืม, หยุดจับฉันแน่นเกินไปนะ PlayerName! คุณกำลังจะทำให้แขนฉันหักครึ่ง...",
  ui_story_5084_50840301_110_dialog_content = "อ-โอ๊ะ โทษที...",
  ui_story_5084_50840301_111_dialog_content = "ที่นั่น, ดีขึ้นเยอะเลย!",
  ui_story_5084_50840301_112_dialog_content = "ฉันต้องคิดอะไรบางอย่าง... แต่ฉันจะทำอะไรได้จริงๆ...?",
  ui_story_5084_50840301_113_dialog_content = "แล้วเกิดอะไรขึ้นระหว่างวิกตอเรียและคุณลุงของเธอกันแน่? ทำไมเขาถึงสละสาวหลานของตัวเอง...?",
  ui_story_5084_50840301_114_dialog_content = "คุณกำลังพยายามคิดแผนอะไรอยู่หรือ PlayerName? เปลวไฟของเทียนกำลังแปรปรวน... ดูสิ, ภาพที่เห็นกำลังเริ่มเปลี่ยนแปลง",
  ui_story_5084_50840401_1_dialog_content = "<color=#e8d9bb>ตุบ ตุบ, ตุบ ตุบ...</color>",
  ui_story_5084_50840401_2_dialog_content = "เสียงนั่น...!",
  ui_story_5084_50840401_3_dialog_content = "เมี้ยว",
  ui_story_5084_50840401_4_dialog_content = "อย่ากลัวนะ มิสเตอร์โบ! ฉันอยู่นี่แล้ว!",
  ui_story_5084_50840401_5_dialog_content = "โชคดีจริง ๆ ที่คุณสองคนยังอยู่ที่นั่น สำหรับสักครู่ฉันคิดว่าฉันจะต้องอยู่คนเดียวอีกครั้ง.",
  ui_story_5084_50840401_6_dialog_content = "ดูเหมือนว่าเราได้มาถึงที่ใหม่ มีกลิ่นหอมบางอย่างด้วย นี่เป็นกลิ่นของเสื้อผ้าที่สะอาด...ใช่มั้ยล่ะ?",
  ui_story_5084_50840401_7_dialog_content = "หา?",
  ui_story_5084_50840401_8_dialog_content = "<color=#e8d9bb>เอี๊ยด—</color>",
  ui_story_5084_50840401_9_dialog_content = "ส-มีคนอยู่ที่นี่!",
  ui_story_5084_50840401_10_dialog_content = "อืมม... นี่, อย่าปิดปากฉัน... อืมม!",
  ui_story_5084_50840401_11_dialog_content = "... ฮืมฟ. ฉันใส่เสื้อผ้าเหล่านี้เมื่อวานนี้ ซึ่งทำให้มันกลายเป็นประวัติศาสตร์โบราณแล้วตอนนี้.",
  ui_story_5084_50840401_12_dialog_content = "และผ้าชิ้นนี้รู้สึกเหมือนกระดาษทรายบนผิวของฉัน! ฉันเป็นศิลปิน ไม่ใช่ช่างไม้รายเล็ก...",
  ui_story_5084_50840401_13_dialog_content = "เรื่องของตัวนี้... สีมันจืดจางไป... ศิลปินที่แท้จริงจะไม่ยอมใส่สีที่ไม่มีชีวิตชีวาแบบนี้เลย",
  ui_story_5084_50840401_14_dialog_content = "เฮ้! นี่ทำขึ้นมาจากร้านเสื้อผ้าเด็กหรือเปล่า?! ฉันอายุมากพอแล้วที่จะใส่เสื้อผ้าผู้ใหญ่!",
  ui_story_5084_50840401_15_dialog_content = "คำสาปทั้งหมด—! ฉันไม่ควรได้ยินคำพูดของพ่อแล้วเอาใจใส่!",
  ui_story_5084_50840401_16_dialog_content = "คู่หูที่ขาดความคิดริเริ่มนั้นไม่มีทางสร้างชุดเรียบร้อยสำหรับคารอนที่ยิ่งใหญ่ได้เลย!",
