  ui_story_5084_50840401_19_dialog_content = "ค-คารอน?!?",
  ui_story_5084_50840401_20_dialog_content = "รอสักครู่... เขาไม่เห็นเราหรือเปล่า?",
  ui_story_5084_50840401_21_dialog_content = "ฮึ่ม ฮึ่ม... ท-ที่สุด คุณก็ปล่อยฉัน! คุณรู้จักเด็กคนนี้ไหม, PlayerName?",
  ui_story_5084_50840401_22_dialog_content = "เย่... ทรงผมนั้นและท่าทางนั้น... ไม่มีทางที่จะสับสน \"คารอนที่ยิ่งใหญ่\" กับใครอื่นได้!",
  ui_story_5084_50840401_23_dialog_content = "เขายืนอยู่ตรงหน้าเราเมื่อกี้นี่เอง ไม่ใช่เหรอ?",
  ui_story_5084_50840401_24_dialog_content = "ใช่ และดูเหมือนว่าเขากำลังเลือกชุดนะ อืมม... เสื้อผ้าที่มีกลิ่นหอมนี้จริง ๆ แล้วดีมาก! ฉันไม่เคยสามารถจัดเตรียมชุดที่ดีเท่านี้ได้...",
  ui_story_5084_50840401_25_dialog_content = "เราอยู่ในตู้เสื้อผ้าของคารอน... แต่จากที่เห็น คารอนคงอายุไม่เกินสิบปี...",
  ui_story_5084_50840401_26_dialog_content = "แต่ก็คง... ฉันไม่เคยทายอายุคนนั้นได้ เดาว่ามันคงไม่สำคัญหรอก เพราะตอนนี้เรากำลังอยู่ในอดีต",
  ui_story_5084_50840401_27_dialog_content = "รอสักครู่... กลับไปที่การปรากฏของความจริง วิกตอเรียบอกว่าเราอยู่ในปี 1915 ซึ่งหมายความว่า...",
  ui_story_5084_50840401_28_dialog_content = "แล้วเรื่องเทียนเล่มนี้ล่ะ? มันส่งฉันไปที่อื่นทุกครั้งที่มันเริ่มแสงกระพริบ และครั้งนี้มันยังพาคุณมาด้วยเลย เมย์!",
  ui_story_5084_50840401_29_dialog_content = "คุณนี่บ้าจริง ๆ นะ PlayerName! มันเกิดขึ้นได้เพราะคุณถือเทียนอยู่ในมือหนึ่ง และมืออีกข้างก็ถือมิสเตอร์โบอยู่เลยนั่นแหละ!",
  ui_story_5084_50840401_30_dialog_content = "ซิคาเรมีวัตถุมหัศจรรย์ที่มีพลังมหาศาลหลากหลายอยู่ในการควบคุมของเธอ แต่ถ้าคุณไม่เชื่อในเวทมนตร์ ก็ไม่มีอะไรจะพูดต่อมากนัก",
  ui_story_5084_50840401_31_dialog_content = "...? คุณไม่กังวลหรืออยากรู้เกี่ยวกับทุกอย่างที่เราเพิ่งเห็นไปหรือ?",
  ui_story_5084_50840401_32_dialog_content = "คุณหมายถึงความอยากรู้อยากเห็นที่ทำให้รู้สึกสุขหรือความอยากรู้อยากเห็นที่ทำให้รู้สึกกลัว?",
  ui_story_5084_50840401_33_dialog_content = "อืม, มันมีความสำคัญอย่างไรล่ะ? ฉันชอบทั้งสอง! ฮ่า ๆ ๆ ๆ!",
  ui_story_5084_50840401_34_dialog_content = "ถ้างั้นเทียนนี้คือเหตุผลที่คารอนไม่สามารถเห็นหรือได้ยินเรา...?",
  ui_story_5084_50840401_35_dialog_content = "เหตุการณ์เดียวกันเกิดขึ้นที่วัดแห่งความจริง... วิกตอเรียจากปัจจุบันเท่านั้นที่สามารถเห็นเราได้",
  ui_story_5084_50840401_36_dialog_content = "มันเหมือนกับไอเทมจากเรื่องราวนั้นๆ! ประเภทที่สามารถทำให้หายตัวได้!",
  ui_story_5084_50840401_37_dialog_content = "ฮ่าฮ่าฮ่า ไม่ได้ล้อเล่นนะ!",
  ui_story_5084_50840401_38_dialog_content = "เราไม่รู้ว่าวิกตอเรียเกิดอะไรขึ้นหลังจากที่เธอเข้าไปในโลงนั้น หรือว่าเนลส์กับเฟาสต์อยู่ที่ไหนตอนนี้...",
  ui_story_5084_50840401_39_dialog_content = "เรามาถึงที่นี่จริง ๆ ด้วยการทำตามคำแนะนำจากหัวใจของเราเหรอ...?",
  ui_story_5084_50840401_40_dialog_content = "คุณคิดอะไรอยู่ก่อนหน้านี้เหรอ?",
  ui_story_5084_50840401_41_dialog_content = "คุณหมายถึงเมื่อแสงเทียนเริ่มริบหรี่หรือ? มันเป็นเหมือนว่า...",
  ui_story_5084_50840401_42_dialog_content = "\"คลาวิส, วิลเฮล์ม, และวิกตอเรีย... พวกเขากำลังวางแผนอะไรกันแน่?\"",
  ui_story_5084_50840401_43_dialog_content = "ถ้าพ่อของคารอนและ\"คู่หูที่ไม่ค่อยฉลาดนั้น\" คือสามคนนั้น...",
