  ui_story_5084_50840502_64_dialog_content = "ถ้าฉันตาย พวกหนอนแมลงนั้นจะไม่ปล่อยเธอไปเด็ดขาด...",
  ui_story_5084_50840502_65_dialog_content = "วิกตอเรีย... วิกตอเรีย...",
  ui_story_5084_50840502_66_dialog_content = "(หืม? เขากังวลเกี่ยวกับวิกตอเรียเหรอ?)",
  ui_story_5084_50840502_67_dialog_content = "ถูกต้อง! ในฐานะผู้นำทรู ออเดอร์ ฉันคือผู้ประกาศเริ่มต้น! แต่...",
  ui_story_5084_50840502_68_dialog_content = "เธอบอกว่าเธอไม่มีเจตนาที่จะอยู่ที่ Advent of Truth คืนนี้... เธออาจจะอยู่ที่ไหนได้บ้าง...?",
  ui_story_5084_50840502_69_dialog_content = "นั่นหมายความว่า วิกตอเรียได้ปรากฏตัวขึ้นในวัดในเวลาที่แย่ที่สุด! เธอจริง ๆ แล้วถูกเสียสละตัวเอง!",
  ui_story_5084_50840502_70_dialog_content = "นั่นใครน่ะ? ออกมานะ...",
  ui_story_5084_50840502_71_dialog_content = "(ไม่นะ, อีกแล้ว...!)",
  ui_story_5084_50840502_72_dialog_content = "อืม, ดังนั้นคุณมีแผนฉุกเฉินในใจหรือเปล่า?",
  ui_story_5084_50840502_73_dialog_content = "PlayerName! นายทำอะไรอีกแล้วเหรอ?!",
  ui_story_5084_50840502_74_dialog_content = "มันจบแล้ว... ทันทีที่เขาพูดถึงการสละสิ่งของของวิกตอเรีย ฉันก็ไม่สามารถหยุดตัวเองได้...",
  ui_story_5084_50840502_75_dialog_content = "การสละสังหารท่านหญิงวิกตอเรีย... รอสักครู่, นั่นคือวันนี้เหรอ? นั่นหมายความว่าเหตุการณ์เดียวกันกำลังจะเกิดขึ้นอีกครั้งเหรอ?!",
  ui_story_5084_50840502_76_dialog_content = "ฉันก็กลัวเหมือนกัน... แม้ว่าวิลเฮล์มจะดูว่ากังวลเรื่องวิกตอเรีย ฉันก็ยังต้องรู้ว่าเขาวางแผนจะทำอะไรกับเธอ...",
  ui_story_5084_50840502_77_dialog_content = "การศึกษานี้... ยังมี<color=#FFB400>สิ่งของของออสเตน วาราคี</color>อยู่ที่นี่หรือไม่?",
  ui_story_5084_50840502_78_dialog_content = "หรือจะเป็น... เขา?",
  ui_story_5084_50840502_79_dialog_content = "บอกฉันสิ! การเสนอวิกตอเรียเป็นสังเวย... นี่คือความประสงค์ของคุณหรือ?",
  ui_story_5084_50840502_80_dialog_content = "\"เขา\"?",
  ui_story_5084_50840502_81_dialog_content = "เมื่อกี้ใครพูดกับคุณ?! บอกฉันมา!",
  ui_story_5084_50840502_82_dialog_content = "นายท่าน...!",
  ui_story_5084_50840502_83_dialog_content = "... อ๊ากกก! <size=45>เปรี้ยงสร้อยคอนรกนี้!!!</size>",
  ui_story_5084_50840502_84_dialog_content = "ฆ่าฉันเถิดค่ะ นายท่าน... ปลดปล่อยฉันจากความทุกข์ทรมานนี้!!!",
  ui_story_5084_50840502_85_dialog_content = "ดูสถานะที่ผิดเพี้ยนของเจ้าสิ... น่าสมเพช",
  ui_story_5084_50840502_86_dialog_content = "อัก... อ๊ากกกกก!",
  ui_story_5084_50840502_87_dialog_content = "อาฮ่าฮ่าฮ่า—! ฉันคือผู้นำที่ถูกต้องแห่งทรู ออเดอร์! ฉัน!!!",
  ui_story_5084_50840502_88_dialog_content = "(แหวนกำลังโจมตีจิตใจของวิลเฮล์มอีกครั้ง... ฉันควรทำอย่างไรดี?)",
  ui_story_5084_50840502_89_dialog_content = "วิลเฮล์ม เจ้าโง่ที่ไม่มีความหวัง ดังที่ข้าได้บอกไว้ก่อนหน้านี้ เจ้าต้องตายเพื่อที่จะอยู่รอด",
  ui_story_5084_50840502_90_dialog_content = "ฉันไม่กลัวความตาย... แต่วิกตอเรีย... เธอจะเป็นยังไง?!?",
  ui_story_5084_50840502_91_dialog_content = "เจ้าแห่งสัจธรรม...",
  ui_story_5084_50840502_92_dialog_content = "บอกฉันสิ วิกตอเรียจะเป็นอย่างไรหลังจากวันนี้...!!!",
  ui_story_5084_50840502_93_dialog_content = "เขาสูญเสียการควบคุมอย่างสมบูรณ์! ถ้าสถานการณ์ยังคงเป็นแบบนี้ เขาจะไม่รอด!",
  ui_story_5084_50840502_94_dialog_content = "ดูเหมือนว่าคุณสามารถติดต่อกับเขาได้ด้วยพลังของคุณ PlayerName ทำไมไม่ลองทำดูสิ?",
  ui_story_5084_50840502_95_dialog_content = "แต่ถ้าฉันทำแบบนั้น อาจจะส่งผลต่ออดีต! เราจะเจอปัญหาใหญ่แน่ถ้าเกิดเรื่องแบบนั้น...",
  ui_story_5084_50840502_96_dialog_content = "คุณเชื่อในเจ้าแห่งสัจธรรมใช่ไหม เมย์? อะไรที่จะทำให้คุณรู้สึกสงบในสถานการณ์แบบนี้โดยไม่ทำให้คนอื่นสงสัย?",
  ui_story_5084_50840502_97_dialog_content = "ฉันไม่รู้สินะ, อะไรง่าย ๆ อย่าง \"ขอความจริงจงสถิตกับท่าน,\" หรือ \"ปฏิบัติตามคำแนะนำ,\" ฉันคิดว่า?",
  ui_story_5084_50840502_98_dialog_content = "จริงหรือ...? คิดว่าน่าลองนะ...",
  ui_story_5084_50840502_99_option_content = "Mindlink—",
  ui_story_5084_50840502_100_dialog_content = "ขอความจริงจงสถิตกับท่าน",
  ui_story_5084_50840502_101_dialog_content = "...",
  ui_story_5084_50840502_102_dialog_content = "ขอความจริงจงสถิตกับท่าน",
  ui_story_5084_50840502_103_dialog_content = "เม-เมย์ ความจริงจงสถิตกับคุณ...",
  ui_story_5084_50840502_104_dialog_content = "แก... แกเป็นใครกันแน่...?",
  ui_story_5084_50840502_105_dialog_content = "(ดูเหมือนว่ามันจะได้ผล แต่ฉันควรระมัดระวังอย่าพูดผิด...)",
  ui_story_5084_50840502_106_dialog_content = "ฉันขอโทษ แต่ฉันไม่สามารถเชื่อในพระเจ้าที่ควบคุมหัวใจของคนได้อีกต่อไป ความจริงในหัวใจของฉันจะไม่นำฉันหลงทาง",
  ui_story_5084_50840502_107_dialog_content = "ทรู ออเดอร์ไม่สามารถดำรงอยู่ในรูปแบบนี้ต่อไปได้ อย่างน้อยไม่ในอนาคตของวิกตอเรีย",
  ui_story_5084_50840502_108_dialog_content = "ถ้าคุณก็เชื่อในเจ้าแห่งความจริง เข้าใจคำพูดของฉันเถอะ",
  ui_story_5084_50840502_109_dialog_content = "สำหรับคุณที่ปรากฏตัวหน้าผมในตอนนี้ มันต้องหมายความว่าคุณมีอะไรจะบอกผม... ถูกต้องไหม?",
  ui_story_5084_50840502_110_dialog_content = "... ทำตามคำแนะนำ",
  ui_story_5084_50840502_111_dialog_content = "... ดังนั้นคุณเชื่อว่าฉันควรยอมรับความจริง และยอมให้ตัวเองถูกกลืนโดยหัวหน้าครอบครัวของเรา...",
  ui_story_5084_50840502_112_dialog_content = "เพื่อให้วิกตอเรียสามารถทนต่อคำสาปของพวกเราได้ และในที่สุดก็ต้องสิ้นชีวิตด้วยมือของแวมไพร์นั่นเหรอ?",
  ui_story_5084_50840502_113_dialog_content = "(ไม่, ไม่ใช่แบบนั้น... ฉันทำให้สถานการณ์แย่ลงได้อย่างไรเนี่ย...?)",
  ui_story_5084_50840502_114_dialog_content = "... ไม่! ไม่ได้เด็ดขาด!",
  ui_story_5084_50840502_115_dialog_content = "ฉันได้มาไกลแล้ว แม้ว่าจะถูกทอดทิ้งโดยครอบครัวของฉัน และฉันขอขอบคุณทั้งหมดนี้กับความจริงที่อยู่ในหัวใจของฉัน! ความจริงนั้นจะไม่เคยนำฉันหลงทาง!",
  ui_story_5084_50840502_116_dialog_content = "มันคือ \"การเปิดเผย\" ที่เรียกว่านี้ที่ทำให้ทรู ออเดอร์ตกต่ำลงเพียงนี้...",
  ui_story_5084_50840502_117_dialog_content = "ฉันต้อง... ถอนคำสาปนี้",
  ui_story_5084_50840502_118_dialog_content = "แต่ยังไง...",
  ui_story_5084_50840502_119_dialog_content = "... สิ่งศักดิ์สิทธิ์เดียวที่ยังไม่ถูกผู้นำทำให้สกปรก... คือ <color=#FFB400>นั่น</color>.",
  ui_story_5084_50840502_120_dialog_content = "พระจันทร์เลือด... เมื่อเถาวัลย์ของมันเปลี่ยนรูปเป็นสิ่งมีชีวิต ผู้พิทักษ์จะรอคนครองหลุมฝังศพที่ปากทาง",
  ui_story_5084_50840502_121_dialog_content = "แต่นอกจากการขนโลงศพของบรรพบุรุษของเราเข้าออกจากหลุมศพ... เส้นทางเดียวที่สามารถเข้าได้คือด้วย <color=#FFB400>กุญแจ</color> หรือด้วยความยินยอมจากหัวหน้าครอบครัวเท่านั้น...",
  ui_story_5084_50840502_122_dialog_content = "ฮ่า! วิลเฮล์ม ไอ้คนน่าสะอิด... ยังคิดถึงกฎเกณฑ์เมื่อกำลังจะถูกกินหรอ? คุณควรถูกหัวเราะเยาะ...",
  ui_story_5084_50840502_123_dialog_content = "ถึงแม้คลาวิสจะปฏิเสธไม่ให้กุญแจฉัน แต่ผู้ดูแลเถาวัลย์ได้รับใช้วารากิมาหลายชั่วคน...",
  ui_story_5084_50840502_124_dialog_content = "แน่นอนเขาจะยอมให้ฉันเข้าสุสานตอนนี้ที่ฉันได้รับความรู้นี้แล้วใช่ไหม?",
  ui_story_5084_50840502_125_dialog_content = "ฉันต้องเข้าไปก่อนที่ขบวนพาเหรดจะเริ่ม!",
  ui_story_5084_50840502_126_dialog_content = "<color=#e8d9bb>ฟู่ว!</color>",
  ui_story_5084_50840502_127_dialog_content = "จับให้แน่น เมย์!",
  ui_story_5084_50840502_128_dialog_content = "คราวนี้เราจะไปไหนกันเนี่ย?!",
  ui_story_5084_50840502_129_dialog_content = "สุสานของวาราคี!",
  ui_story_5084_50840601_1_dialog_content = "<color=#e8d9bb>ที่ประตูเข้าร้านช่างตัดเสื้อในเมืองวาราคี</color>",
  ui_story_5084_50840601_2_dialog_content = "เมย์ความจริงจงสถิตกับคุณ, ช่างเย็บผ้าที่มีฝีมือ.",
  ui_story_5084_50840601_3_dialog_content = "และขอความจริงจงสถิตกับท่านเช่นกัน ท่านผู้ที่ใจดี ด้วยรูปลักษณ์ที่เคารพบุญอย่างนี้ ท่านแน่นอนจะถูกเลือกเป็นผู้ริเริ่มในปีนี้",
  ui_story_5084_50840601_4_dialog_content = "ฉันหวังว่ามันจะเป็นอย่างนั้น ที่รักของฉัน ฉันต้องไปแล้ว; จนกว่าเราจะพบกันที่งานเลี้ยงคืนนี้ อย่ามาสายนะครับ.",
  ui_story_5084_50840601_5_dialog_content = "ฉันรับรองว่าฉันจะไม่",
  ui_story_5084_50840601_6_dialog_content = "อะไรเนี่ย... เรามาอยู่ที่นี่ได้ยังไงน่ะ?",
  ui_story_5084_50840601_7_dialog_content = "คุณมาที่นี่เพื่อผ้าคลุมในพิธีนี้หรือไม่ครับ?",
  ui_story_5084_50840601_8_dialog_content = "เสื้อคลุมพิธีการ...?",
  ui_story_5084_50840601_9_dialog_content = "อ่า คุณคงเป็นลูกค้าของคนอื่นแน่ ๆ",
  ui_story_5084_50840601_10_dialog_content = "คุณควรรู้ว่า ตระกูลช่างตัดเสื้อของเราได้ดำเนินธุรกิจนานที่สุดที่นี่ในเมืองวาราคี ในทุกๆ ครั้งที่มี Advent of Truth เรามีร้านค้าจัดการออร์เดอร์สำหรับชุดคลุมมากที่สุดเช่นกัน",
  ui_story_5084_50840601_11_dialog_content = "แม้แต่คนที่อาศัยอยู่ที่ชายขอบเมืองของเราก็จะมาซื้อเสื้อคลุมของเราในคืนที่มีการฉลองเลย",
  ui_story_5084_50840601_12_dialog_content = "เลยทำไมไม่สั่งซื้อกับเราล่ะ? ฉันรับประกันว่าราคาจะถูกใจคุณแน่นอน",
  ui_story_5084_50840601_13_dialog_content = "...",
  ui_story_5084_50840601_14_dialog_content = "ดูสิเพื่อน! พระจันทร์เลือดได้ปรากฏตัวแล้ว",
  ui_story_5084_50840601_15_dialog_content = "พระจันทร์เลือด... การมาถึงของความจริงคืนนี้...",
  ui_story_5084_50840601_16_dialog_content = "พี่เลี้ยงของฉันบอกว่าเขาจะเลือกฉันเป็นผู้ริเริ่มในปีนี้ ซึ่งหมายความว่าฉันต้องแต่งกายอย่างเครื่องสักการะบูชาสำหรับโอกาสนี้",
  ui_story_5084_50840601_17_dialog_content = "ผู้เริ่มต้น?! ฉันได้ยินถูก...?",
  ui_story_5084_50840601_18_dialog_content = "แต่คนเดียวที่สามารถประกาศเริ่มต้นคือลอร์ดวิลเฮล์ม วารากิ! ทำไมเขาถึงเลือกคุณจากทุกคนล่ะ?",
  ui_story_5084_50840601_19_dialog_content = "ใช่ครับ นั่นคือชื่อของที่ปรึกษาของฉัน พวกเราได้พบกันในห้องศพของครอบครัวเขา",
  ui_story_5084_50840601_20_dialog_content = "สุสานของวารากิ...?! ฉันเห็นแล้ว... บอกฉันสิ, คุณจัดการยังไงถึงจะเข้าใกล้กับความจริงได้ขนาดนั้น?",
  ui_story_5084_50840601_21_dialog_content = "...ฉันสารภาพบาปและขอการชดใช้ทุกวัน แต่ทุกคนยังคงหลีกเลี่ยงฉัน ทุกคน...ยกเว้นอาจารย์ของฉัน.",
  ui_story_5084_50840601_22_dialog_content = "การชดใช้... การปรากฏของความจริง... และดวงจันทร์เลือด... ใช่ ฉันคิดว่าฉันเข้าใจแล้ว...",
  ui_story_5084_50840601_23_dialog_content = "ขอบคุณที่ส่งมอบความรู้เกี่ยวกับความจริงให้ฉันนะครับ ผู้ริเริ่มที่เคารพ...",
  ui_story_5084_50840601_24_dialog_content = "ฉันได้รับเงินจากผู้ศรัทธาในนามของการมาถึงของความจริง... และด้วยเหตุนี้ ความจริงจึงได้หันหลังให้ฉัน...",
  ui_story_5084_50840601_25_dialog_content = "พระเจ้าสถิตกับท่าน ผู้ริเริ่ม... พระเจ้าสถิตกับท่านที่ได้ชี้แนะความผิดของข้าพเจ้าให้รู้",
  ui_story_5084_50840601_26_dialog_content = "คุณจะรังเกียจที่จะให้เกียรติเราด้วยการปรากฏตัวของคุณอีกสักครู่ไหม? แม่ของฉัน, ลูกสาวของฉัน, และฉันจะเป็นเกียรติที่จะทำชุดเสื้อผ้าสำหรับคุณด้วยความเร่งด่วนที่สุด!",
  ui_story_5084_50840601_27_dialog_content = "น-นั่นไม่จำเป็น... ฉันแค่ผ่านมาในการค้นหาที่ปรึกษาของฉันเท่านั้นน่ะ",
  ui_story_5084_50840601_28_dialog_content = "นี่ไม่ใช่เรื่องบังเอิญครับ; ความจริงแท้นี่แหละที่ชักนำคุณมาที่นี่ในวันนี้! โปรดยกโทษให้ฉันที่ทำตัวหยาบคายเมื่อสักครู่—",
  ui_story_5084_50840601_29_dialog_content = "อีกครั้ง, มันไม่จำเป็นจริงๆ...",
  ui_story_5084_50840601_30_dialog_content = "แม่? แม่ยังทำอะไรอยู่ที่นี่?! กลุ่มลูกค้าเราเบื่อรอแล้ว!",
  ui_story_5084_50840601_31_dialog_content = "บอกพวกเขาว่าเราจะส่งเสื้อคลุมให้พวกเขาฟรีวันนี้!",
  ui_story_5084_50840601_32_dialog_content = "ฮา?",
  ui_story_5084_50840601_33_dialog_content = "หลังจากนี้ เราจะทำชุดเสื้อผ้าให้หนุ่มน้อยคนนี้ทันที! เขาคือผู้ริเริ่ม!",
  ui_story_5084_50840601_34_dialog_content = "คุณหมายถึงตอนนี้เหรอ?",
  ui_story_5084_50840601_35_dialog_content = "ใช่แล้วละ ที่รัก!",
  ui_story_5084_50840601_36_dialog_content = "คุณยายจะไม่มีความสุขเกี่ยวกับสิ่งนี้...",
  ui_story_5084_50840601_37_dialog_content = "ทำตามที่ฉันบอกเถอะ เด็ก ตอนนี้ ฉันจะอธิบายทุกอย่างให้คุณยายฟัง",
  ui_story_5084_50840601_38_dialog_content = "ได้สิ...",
  ui_story_5084_50840601_39_dialog_content = "อ๊ะ... โปรดยกโทษให้ข้าด้วย เจ้าแห่งสัจธรรม! ดูเหมือนว่าข้าได้ทำความผิดอีกครั้ง...",
  ui_story_5084_50840601_40_dialog_content = "ขอบคุณพระเจ้า... ฉันยังมีเงินบางส่วนอยู่กับตัว... ฉันหวังเพียงว่ามันจะช่วยปิดบัญชีค่าเสียหายของพวกเขาในวันนี้บ้าง...",
  ui_story_5084_50840601_41_dialog_content = "แต่ฉันไม่ควรกดดันช่างเย็บผ้าแบบนี้หรือครอบครัวของเธออีกต่อไป...",
  ui_story_5084_50840601_42_dialog_content = "วิลเฮล์ม.",
  ui_story_5084_50840601_43_dialog_content = "ใครกล้าพูดชื่อข้าและขวางทางข้า?! ออกจากทาง! การปรากฏตัวของความจริงต้องการความอยู่ของข้า!",
  ui_story_5084_50840601_44_dialog_content = "คุณได้สูญเสียการมองเห็นสัจธรรม และมุมมองของคุณถูกบดบังด้วยความเป็นจริงแทน",
