  ui_story_5084_50840601_57_dialog_content = "แต่... ยังไง?",
  ui_story_5084_50840601_58_dialog_content = "<color=#FFB400>กุญแจ</color>อยู่ใกล้ๆนี่... ฉันสัมผัสได้ถึงเปลวไฟของมัน",
