  ui_story_5084_50840601_66_dialog_content = "โชคชะตาได้นำทางฉันมาที่นี่ ซึ่งหมายความว่า พระเจ้าแห่งความจริงปรารถนาให้ฉันปฏิบัติตามคำสั่งศักดิ์สิทธิ์ของพระองค์",
