  ui_story_5084_50840602_36_dialog_content = "คุณควรห่วงตัวเองก่อนนะ คนโง่! ฮ่าฮ่าฮ่าฮ่า!",
  ui_story_5084_50840602_37_dialog_content = "วิลเฮล์ม...!",
  ui_story_5084_50840602_38_dialog_content = "ท่านลอร์ดของข้า โปรดมอบความทุกข์สุขให้ข้า และอนุญาตให้ข้าทนทุกข์แทนท่าน กลืนมัน ปล่อยมัน และให้ความจริงครองเหนือความชั่ว...",
  ui_story_5084_50840602_39_dialog_content = "ไม่ คุณเนลส์! คุณต้องวิ่ง—",
  ui_story_5084_50840602_40_dialog_content = "หยุด, เมย์! เราไม่ได้รับอนุญาตให้แทรกแซง... จำไว้ว่าซิคาเรเคยบอกเรา!",
  ui_story_5084_50840602_41_dialog_content = "นี่เป็นความผิดของฉันทั้งหมด ถ้าฉันเงียบไว้ก็คงไม่มีอะไรเกิดขึ้น... เราต้องคิดวิธีอื่นในการช่วยเขา ฉันยังมีเทียนเทศกาลอยู่ คงต้องมีอะไรที่เราทำได้",
  ui_story_5084_50840602_42_dialog_content = "ฮึม, น่าประหลาดจริง ๆ ดูเหมือนว่ากระดูกของคุณจะแข็งแกร่งเท่ากับความศรัทธาของคุณเลยล่ะ",
  ui_story_5084_50840602_43_dialog_content = "ตาย!",
  ui_story_5084_50840602_44_dialog_content = "เจ้าแห่งความจริง พิธีกรรมของคุณโหดร้ายจนไม่สามารถทนได้ ผู้ที่ศรัทธาคุณจริง ๆ สามารถทนต่อได้หรือไม่? ถ้าได้ พวกเขาจะรอดจากความเจ็บปวดที่มหาศาลนี้อย่างไร?",
  ui_story_5084_50840602_45_dialog_content = "ฉันจะทนมัน! ฉันจะกลืนความทุกข์ทรมานนี้และล้างบาปที่ปะปนอยู่ในร่างกายของฉัน ฉันจะยอมรับคำสาปของความเจ็บปวดนี้และเผาไฟแผลที่ฝังอยู่ในจิตวิญญาณของฉัน—",
  ui_story_5084_50840602_46_dialog_content = "อนุญาตให้ฉันทนความเจ็บปวดนี้เป็นคนเดียว โดยไม่ให้คนอื่นต้องประสบกับมัน! มาลบล้างบาปของฉันผ่านความทุกข์ทรมาน!",
  ui_story_5084_50840602_47_dialog_content = "ชีวิตที่เต็มไปด้วยความทุกข์ทรมานเพื่อแลกเปลี่ยนกับการได้รับการล้างบาปของพวกเขา!",
  ui_story_5084_50840602_48_dialog_content = "(ด้วยสภาพนี้ เนลส์จะตายอย่างแน่นอนในมือพวกเขา! มาสิ ตะเกียง... พาฉันไปที่ที่ฉันสามารถทำให้มีความแตกต่าง...!)",
  ui_story_5084_50840602_49_dialog_content = "คุณโง่!",
  ui_story_5084_50840602_50_dialog_content = "นี่ไม่ใช่พิธีกรรม และพวกเขาไม่ได้ช่วยคุณล้างจิตใจ! คุณไม่เห็นหรอว่าพวกเขากำลังพยายามฆ่าคุณเหรอ?!",
  ui_story_5084_50840602_51_dialog_content = "คุณมองตัวเองว่าเป็นผู้นิราศหรือไม่? ถ้าใช่ คุณต้องรอดชีวิตและอุทิศชีวิตที่เหลือของคุณเพื่อการค้นหาสัจธรรม!",
  ui_story_5084_50840602_52_dialog_content = "นายท่าน?",
  ui_story_5084_50840602_53_dialog_content = "อยู่รอดซะ เจ้าโง่!",
  ui_story_5084_50840602_54_dialog_content = "<color=#e8d9bb>วิลเฮล์มจับเนลส์แล้วโยนเขาออกไปด้วยความแข็งแกร่งที่น่าประหลาดใจ เขาชนประตูวัด ทำให้ประตูเปิดอ้างกว้าง และทำให้ลมสีดำสามารถเข้ามาได้</color>",
  ui_story_5084_50840602_55_dialog_content = "อ๊ะ! เทียนดับแล้ว!",
  ui_story_5084_50840602_56_dialog_content = "วิลเฮล์ม วาราคิจะไม่ถูกบังคับให้คุกเข่าง่าย ๆ แบบนี้! ตอนนี้คุณมีอะไรเตรียมไว้ให้ฉันอีกบ้าง?!",
  ui_story_5084_50840602_57_dialog_content = "คุณปีศาจทรยศจะได้ชิมคมดาบของฉันก่อนที่คืนจะผ่านไป!",
  ui_story_5084_50840602_58_dialog_content = "ตื่นขึ้นมาเถอะ, <color=#FF0000>สายธารสีเลือด</color>! ดาบปีศาจของฉัน ที่ดื่มเลือดของฉันเพื่อแลกเปลี่ยนกับการตัดลงศัตรูของฉัน!",
  ui_story_5084_50840602_59_dialog_content = "เกิดอะไรขึ้น? พวกเขากำลังจะต่อสู้...?",
  ui_story_5084_50840602_60_dialog_content = "ฉันไม่รู้! ฉันไม่เห็นอะไรเลย!",
  ui_story_5084_50840602_61_dialog_content = "โลกกำลังเริ่มเปลี่ยนแปลงรอบ ๆ เราอีกครั้ง แต่ฉันต้องดูสิ่งนี้จนจบ! ฉันไม่สามารถปล่อยให้ตัวเอง... ถูกโทรพอร์ตไป—",
  ui_story_5084_50840602_62_dialog_content = "จับฉันไว้และถอยไปให้ไกลที่สุดที่เธอทำได้, เมย์!",
  ui_story_5084_50840602_63_dialog_content = "โธ่, ฉันมองไม่เห็นอะไรในนี้เลย.",
  ui_story_5084_50840602_64_dialog_content = "แม้กระนั้น คนเดียวเขาก็ไม่อาจทนได้นานแค่ไหน",
  ui_story_5084_50840602_65_dialog_content = "อ๊ะ!",
  ui_story_5084_50840602_66_dialog_content = "คนไหนในคุณที่จะเป็นเหยื่อของฉันต่อไป?",
  ui_story_5084_50840602_67_dialog_content = "มายืนข้างฉันสิ Clavis! เราสามารถทำลายพวกเขาได้ด้วยกัน!",
  ui_story_5084_50840602_68_dialog_content = "...",
  ui_story_5084_50840602_69_dialog_content = "มันเป็นสิ่งที่ไร้สาระ, วิลเฮล์ม แม้ว่าคุณจะตัดหัวฉัน ฉันก็ไม่ตาย",
  ui_story_5084_50840602_70_dialog_content = "แล้วฉันจะตัดแกต่อไปจนกว่าแกจะทนความเจ็บปวดไม่ไหวแล้ว!",
  ui_story_5084_50840602_71_dialog_content = "น่าทึ่ง... แม้ว่าเขาจะต้องต่อสู้กับคนเยอะ ๆ ในที่มืด... เขาก็ไม่ได้เป็นฝ่ายเปรียบเลย",
  ui_story_5084_50840602_72_dialog_content = "น่าสงสาร... คุณกำลังพยายามที่จะฆ่าเขาหรือไม่?",
  ui_story_5084_50840602_73_dialog_content = "พูดง่ายกว่าที่จะทำ...",
  ui_story_5084_50840602_74_dialog_content = "ยังคิดว่าจะพึ่งใครได้หรือเปล่า พอร์ฟิริโอ? วันสิ้นสุดของคุณใกล้เข้ามาแล้ว และไม่มีใครจะมาช่วยคุณหนีจากมัน!",
  ui_story_5084_50840602_75_dialog_content = "คุณจำข้อตกลงของเราได้ไหม... จริงไหม?",
  ui_story_5084_50840602_76_dialog_content = "...",
  ui_story_5084_50840602_77_dialog_content = "<size=45>อา-!!!</size>",
  ui_story_5084_50840602_78_dialog_content = "เกิดอะไรขึ้น? ฉันไม่รู้สึกถึงการหายใจของเขาแล้ว! เขา...",
  ui_story_5084_50840602_79_dialog_content = "เพียงแค่ยังคงทนต่อไป! เรา... เรากำลังจะถูกโทรพอร์ตไปที่อื่น!",
  ui_story_5084_50840602_80_dialog_content = "ทำไม... ทำไมมันต้องเป็นแบบนี้ด้วย?",
  ui_story_5084_50840602_81_dialog_content = "(ถ้าเขาตายจริง ๆ ... จะเกิดอะไรขึ้นกับวิกตอเรียเหรอ?)",
  ui_story_5084_50840602_82_dialog_content = "เฮ้, PlayerName? คุณวิลเฮล์มดูไม่เหมือนคนที่จะฆ่าคนเย็นชาเลยใช่ไหม? คุณคิดจริง ๆ ว่าเขาได้สังหารท่านหญิง... วิกตอเรีย...?",
  ui_story_5084_50840602_83_dialog_content = "ฉันก็มีความสงสัยเกี่ยวกับมันตอนนี้ด้วย... ตั้งแต่ตอนที่เทียนแท่งแรกๆ ที่ย้ายเราไป วิลเฮล์มที่เราเห็นนั้นไม่เหมือนกับวิลเฮล์มที่เราเคยเห็นในพิธีของการมาถึงของความจริง...",
  ui_story_5084_50840602_84_dialog_content = "คำพูดของฉันจริงๆ ทำให้เกิดการเปลี่ยนแปลงทั้งหมดนี้ขึ้นหรือ...?",
  ui_story_5084_50840602_85_dialog_content = "หรือว่ามีอะไรอื่นเกิดขึ้นระหว่างวิลเฮล์มที่เราเคยเห็น...?",
  ui_story_5084_50840602_86_dialog_content = "ฉันสงสัยว่าท่านหญิงวิกตอเรียอยู่ที่ไหนตอนนี้...",
  ui_story_5084_50840602_87_dialog_content = "ในระหว่างพิธี วิกตอเรียได้กล่าวถึงเรื่องวิลเฮล์มหายตัวไป บางทีเธอกำลังพยายามหาคำตอบเบื้องหลังการหายตัวของเขาเสมอไหม?",
  ui_story_5084_50840602_88_dialog_content = "มีอะไรบางอย่างบอกฉันว่าพิธีสังหารนี้ไม่ง่ายเท่าที่ดู... ถ้าเธอยินดีที่จะทบทวนทุกอย่างนี้ แสดงว่าเธอกำลังมองหาสิ่งบางอย่าง",
  ui_story_5084_50840602_89_dialog_content = "ดูเหมือนว่าเธอและวิลเฮล์มเข้าใจผิดกันมานาน... พวกเขายังมีอะไรที่ต้องการจะบอกกันอีก.",
  ui_story_5084_50840700_1_dialog_content = "ว้าว, ดูทั้งหมดเหล่าเทียนและดอกไม้นี้สิ, PlayerName! รอสักครู่... นั่นโลงศพหรือ?!",
  ui_story_5084_50840700_2_dialog_content = "คิดว่าใช่นะ...",
  ui_story_5084_50840700_3_dialog_content = "สงสัยว่าตอนนี้เราอยู่ที่ไหนเนี่ย?",
  ui_story_5084_50840700_4_dialog_content = "ข้างนอกมันก็มืดและหม่นหมองเหมือนกัน ขอมาดูสักหน่อย...",
  ui_story_5084_50840700_5_dialog_content = "เราอยู่ในปราสาทโบราณที่ยื่นไปถึงภาคเขา! ใครจะสร้างบ้านของพวกเขาในที่แบบนี้...?",
  ui_story_5084_50840700_6_dialog_content = "<color=#e8d9bb>ตุบ ตุบ, ตุบ ตุบ—</color>",
  ui_story_5084_50840700_7_dialog_content = "อ๊ะ—นี่คือคุณวิกตอเรีย!",
  ui_story_5084_50840700_8_dialog_content = "แต่ว่า... เพราะฉันเพิ่งคิดถึงเธอเมื่อกี้หรือเปล่า?",
  ui_story_5084_50840700_9_dialog_content = "เดี๋ยว, มีคนอื่นอยู่นะ",
  ui_story_5084_50840700_10_dialog_content = "เธอมาค้นหาวิลเฮล์มด้วยเหรอ?",
  ui_story_5084_50840700_11_dialog_content = "นอกจากครอบครัวแล้ว ดูเหมือนว่าคนที่มาที่บ้านของเขามีเพียงแค่ศัตรูของเขาเท่านั้น",
  ui_story_5084_50840700_12_dialog_content = "คุณรู้ไหมว่าเขาอยู่ที่ไหน?",
  ui_story_5084_50840700_13_dialog_content = "น่าเสียดายที่ฉันไม่รู้. เขาไม่ได้ทิ้งเบาะแสเกี่ยวกับที่อยู่ของเขาไว้ก่อนที่เขาจะหายตัวไป",
  ui_story_5084_50840700_14_dialog_content = "เป็นเรื่องน่าเสียดายจริง ๆ ฉันคิดว่าเขาอย่างน้อยก็ควรมีผู้ที่เขาไว้ใจอยู่หนึ่งหรือสองคน",
  ui_story_5084_50840700_15_dialog_content = "เราเคยใกล้ชิดกันขนาดนั้น ใช่",
  ui_story_5084_50840700_16_dialog_content = "ถ้าวิลเฮล์มไม่ทำตัวเสี่ยงเสมอ... มันคงยังคงอยู่แบบนั้นได้",
  ui_story_5084_50840700_17_dialog_content = "คุณไม่เคยเข้าใจคุณลุงของคุณเท่าไหร่เลยนะ... ใช่ไหม วิกตอเรีย?",
  ui_story_5084_50840700_18_dialog_content = "ฉันไม่มีความสนใจที่จะรู้จักคนเช่นเขาเลย ยิ่งแล้วก็ไม่ต้องการที่จะเข้าใจพวกเขา",
  ui_story_5084_50840700_19_dialog_content = "ก่อนที่พ่อของคุณจะกลายเป็นผู้นำของทรู ออเดอร์ คุณลุงวิลเฮล์มของคุณต้องการบทบาทนั้นมากกว่าอะไรอื่น",
  ui_story_5084_50840700_20_dialog_content = "ถูกครอบงำโดยความหวังในความร่ำรวยและความเจริญรุ่งเรือง ทำให้เขากระตือรือร้นในการแสวงหาความเชื่อที่สุดขั้วและประกาศพวกมันเป็นความจริง",
  ui_story_5084_50840700_21_dialog_content = "เพราะสิ่งนี้ เขาเสียควบคุมตัวเองไปซ้ำๆ ทุกครั้งที่พยายามรับมรดกพลังจากบรรพบุรุษของเรา... ถึงเขาจะถูกมองเห็นเป็นคนที่ถูกขับไล่ แต่เขาก็ไม่ยอมรับความพ่ายแพ้",
  ui_story_5084_50840700_22_dialog_content = "การปฏิเสธนั้น ในที่สุดกลับทำให้เขากลายเป็นมารยาทของความทะเยอทะยานของคนอื่น ซึ่งสุดท้ายแล้วก็นำไปสู่การถูกขับไล่ออกจากตระกูลของเขา",
  ui_story_5084_50840700_23_dialog_content = "... ฉันไม่สนใจจะศึกษาเรื่องราวของเขา.",
  ui_story_5084_50840700_24_dialog_content = "ฉันจริงๆ ก็พอใจที่ได้หลุดพ้นจากการควบคุมของเขา",
  ui_story_5084_50840700_25_dialog_content = "ในระหว่างการเดินทางของฉัน เจ้าแห่งสัจธรรมได้เปิดเผยบางสิ่งให้ฉันรู้... ซึ่งเป็นเหตุผลว่าทำไมฉันถึงมาบอกลา",
  ui_story_5084_50840700_26_dialog_content = "ฉันกำลังจะออกเดินทางไปยังสถานที่ที่ฉันเคยเห็น ที่ฉันจะรอคอยการมาถึงอย่างยิ่งใหญ่ของเจ้าแห่งความจริง",
  ui_story_5084_50840700_27_dialog_content = "คุณคือผู้สืบสันดานสายเลือดวารากิ คุณมีอิสระในการตัดสินใจอย่างที่คุณเห็นสมควร",
  ui_story_5084_50840700_28_dialog_content = "แต่ก่อนที่ฉันจะออกไป ฉันขอถามคุณเรื่องอะไรสักอย่างได้ไหม? วันนั้น เมื่อเราไปเยี่ยมบ้านของคุณ... วิลเฮล์มต้องการยืมอะไรจากคุณ?",
  ui_story_5084_50840700_29_dialog_content = "That <color=#FFB400>key</color> will only bring you harm.",
  ui_story_5084_50840700_30_dialog_content = "Just before he died, my brother took it back from the <color=#FFB400>Vinekeepers</color> and gave it to you... Clearly, it was to ensure that the key would make it into my hands someday.",
  ui_story_5084_50840700_31_dialog_content = "... Or perhaps it was to prevent you from forcibly taking it from the <color=#FFB400>Vinekeepers</color> yourself.",
  ui_story_5084_50840700_32_dialog_content = "...! มันคือกุญแจที่เปิดทุกประตู... แต่ผู้ที่มีความทะเยอทะยานจะถูกมันกลืนกินเท่านั้นเอง",
  ui_story_5084_50840700_33_dialog_content = "... ดูแลตัวเองด้วยนะ วิกตอเรีย วาราคี คุณกำลังรับภาระที่หนักและยิ่งใหญ่ และเส้นทางสู่ความจริงนั้นยาวนานและเหนื่อยยาก",
  ui_story_5084_50840700_34_dialog_content = "<color=#e8d9bb>วิกตอเรียมองเมื่อคลาวิสลาออกไป หลังจากที่เขาหายจากสายตา เธอหันไปและเข้าห้องวิลเฮล์ม</color>",
  ui_story_5084_50840700_35_dialog_content = "คุณไปไหนมาเนี่ย ผู้ชายที่ไม่สามารถเข้าใจได้?",
  ui_story_5084_50840700_36_dialog_content = "<color=#e8d9bb>เธอมองรอบ ๆ ห้องก่อนที่จะเปิดโลงศพหรูหราของวิลเฮล์มและนอนลงไปในนั้น</color>",
  ui_story_5084_50840700_37_dialog_content = "ถ้าฉันเห็นสิ่งต่างๆเหมือนพ่อแม่ฉันเคยเห็น... ฉันจะสามารถเข้าใจความทะเยอทะยานของคุณได้หรือไม่?",
  ui_story_5084_50840700_38_dialog_content = "(ความรู้สึกนี้... เธอกำลังพยายามจำอะไรสักอย่าง...)",
  ui_story_5084_50840700_39_dialog_content = "เรามารวมตัวกันที่นี่วันนี้เพื่อเป็นเกียรติแก่หัวหน้าตระกูลวาราคีในขณะที่เรานำร่างกายของพวกเขาไปสู่สุคติภูมิ",
  ui_story_5084_50840700_40_dialog_content = "ตามรอยเท้าของบรรพบุรุษชนชั้นสูงของเรา พวกเขายังมีลูกสาวที่รัก—วิกตอเรีย วาราคี อยู่รอดไว้",
  ui_story_5084_50840700_41_dialog_content = "มาเถอะ เด็กคนนี้; วางแหวนนี้ลงบนหลุมศพของพ่อด้วยมือของคุณเอง มันเป็นสัญลักษณ์ของเกียรติยศของเขา และควรจะได้รับการยกย่องในช่วงเวลานี้",
  ui_story_5084_50840700_42_dialog_content = "พ่อ... แม่...",
  ui_story_5084_50840700_43_dialog_content = "ให้เวลากับตัวเองสักหน่อยนะ ที่รัก เราเข้าใจว่าเธอยังรู้สึกสับสนและเศร้าอยู่",
  ui_story_5084_50840700_44_dialog_content = "แต่อย่ากลัวนะคะ ท่านหญิง เพราะเราจะอยู่ข้างๆ ท่านในชั่วโมงที่มืดมิดที่สุดนี้—อ๊ะ แต่ท่านหญิง ผมลืมแนะนำตัว ผมชื่อเดวิด ปอร์ฟิริโอครับ",
  ui_story_5084_50840700_45_dialog_content = "พ่อของเธอเคยช่วยฉันจำบังความวุ่นวายในเลือดของฉัน และฟื้นฟูความสามารถในการคิดริเริ่มที่มีค่าของฉัน",
