  ui_story_5084_50840700_82_dialog_content = "<color=#e8d9bb>สายฟ้าฟาดผ่าฟ้าด้านนอกขณะที่วิกตอเรียเด็กผู้หญิงเปิดโลงศพของพ่อแม่แล้วคลานเข้าไปในนั้น</color>",
  ui_story_5084_50840700_83_dialog_content = "Father... Mother...",
  ui_story_5084_50840700_84_dialog_content = "ให้ฉันคำแนะนำของคุณ... บอกฉันว่าต้องทำอะไร...",
  ui_story_5084_50840700_85_dialog_content = "ฉัน... ถึงบ้านแล้วเหรอ? แต่... ได้ยังไงล่ะ?",
  ui_story_5084_50840700_86_dialog_content = "<color=#e8d9bb>เสียงกรอบแกรบ, เสียงกรอบแกรบ—</color>",
