  ui_story_5084_50840700_109_dialog_content = "มิฉะนั้น คุณก็ไม่ดีกว่าเด็กดื้อเลย",
  ui_story_5084_50840700_110_dialog_content = "ฉันต้องแข็งแกร่งขึ้น เพื่อไม่ให้ใครสามารถควบคุมฉันได้อีก",
  ui_story_5084_50840700_111_dialog_content = "เพื่อประสงค์นี้ ฉันได้พยายามสืบหาความจริงโดยพยายามสัมผัสกับวัตถุโบราณหลายชิ้นผ่านพิธีกรรมโบราณ...",
  ui_story_5084_50840700_112_dialog_content = "ที่ไหนเหรอ? ข้อความโบราณนั้นอยู่ที่ไหนเนี่ย...?",
  ui_story_5084_50840700_113_dialog_content = "พระเจ้าแห่งความจริงปรากฏตัวในฝันของฉัน ชักชวนฉันที่จะหาคัมภีร์ศักดิ์สิทธิ์ของพระองค์ก่อนที่วิลเฮล์ม วารากีจะสังเกตว่าฉันหายไป...",
  ui_story_5084_50840700_114_dialog_content = "อ๊ะ!",
  ui_story_5084_50840700_115_dialog_content = "<color=#FFB400>ดวงดาว</color>... มันกำลังกลืนกิน <color=#FFB400>ดวงดาว</color>... ไม่มีเวลา! ไม่มีเวลาเลย... <color=#FFB400>การเริ่มต้นใหม่</color> กำลังจะมาถึง...",
  ui_story_5084_50840700_116_dialog_content = "<size=45>จุดจบที่แท้จริงอยู่ภายในความมืดนั้น—!</size>",
  ui_story_5084_50840700_117_dialog_content = "ปล่อยมันทันทีเถอะ คนโง่! มันกล้ามากที่จะพยายามสัมผัสกับของเก่าโบราณนั้น!",
  ui_story_5084_50840700_118_dialog_content = "ความรู้สึกของวันวาน, คำเปิดเผยของคนบ้า—ฉัน, วิลเฮล์ม วารากี, สั่งให้คุณอยู่ห่างจากเธอ!",
  ui_story_5084_50840700_119_dialog_content = "... อ๊ะ!",
  ui_story_5084_50840700_120_dialog_content = "... กลับไปหลับใหลอยู่ในความเงียบสงบอันนิรันดร์ของคุณ.",
  ui_story_5084_50840700_121_dialog_content = "ย-คุณช่วยฉัน? แต่คุณรู้ได้ยังไงว่าฉัน...",
  ui_story_5084_50840700_122_dialog_content = "เรียนรู้ที่จะแยกแยะคุณลักษณะของเรลิกที่แตกต่างกัน หรือไม่งั้นซากศพของคุณจะเป็นสิ่งเดียวที่ฉันเก็บกวาดในครั้งถัดไป",
  ui_story_5084_50840700_123_dialog_content = "และอย่าเข้าใจผิดเกี่ยวกับเจตนาของฉัน ในฐานะผู้นำของทรู ออเดอร์ สิ่งสุดท้ายที่ฉันต้องการคือให้ผู้ศรัทธากล่าวหาฉันว่าทำร้ายลูกสาวของพี่ชายที่เสียชีวิตแล้ว",
  ui_story_5084_50840700_124_dialog_content = "การทำให้คุณมีชีวิตรอดเท่านั้นที่จะช่วยให้ฉันมั่นใจในตำแหน่งของฉัน",
  ui_story_5084_50840700_125_dialog_content = "อีกทั้ง แทนที่จะช่วยคนที่อยู่ในช่วงขอบเขตของความตาย ครอบครัวของเลือดมักจะเลือกที่จะดูดเลือดทุกหยดสุดท้ายจากร่างกายของพวกเขา",
  ui_story_5084_50840700_126_dialog_content = "วิลเฮล์ม วาราคี...!",
  ui_story_5084_50840700_127_dialog_content = "ผู้ชายที่อวดดี หยิ่งยโส และน่ารังเกียจนั่น... เขาได้ยึดชีวิตและอิสระของฉันไป และเหตุผลที่เขาทำเช่นนั้นมักจะแปลกประหลาดเสมอ",
  ui_story_5084_50840700_128_dialog_content = "แต่เมื่อเทียบกับลุงที่ฉันเกลียด คนอื่น ๆ ก็ไม่ดีขึ้นมากเท่าไหร่นัก",
  ui_story_5084_50840700_129_dialog_content = "หัวหน้าครอบครัวทั้งหมดเป็นคนโง่ที่มีหัวใจดำ ทุกคนสุดท้าย คนที่พวกเขานำทางเหมือนกับหนอนหรือศพที่ถูกเรียกคืนชีพ ที่เดินเที่ยวอยู่ในเมืองโดยไม่มีจุดประสงค์หรือความรู้สึก",
  ui_story_5084_50840700_130_dialog_content = "คำสั่งสอนของพวกเขาเต็มไปด้วยความชั่วร้ายและความเขลา และไม่มีคำแนะนำสำหรับผู้ศรัทธาของความจริง คนเหล่านี้ไม่สมควรที่จะเป็นผู้นำทางสำหรับผู้ที่หลงทาง",
  ui_story_5084_50840700_131_dialog_content = "ฉันต้องระวังพวกเขา... ฉันไม่สามารถปล่อยให้ตัวเองกลายเป็นเหยื่อของลัทธินอกรีตอย่างทรู ออเดอร์ได้",
  ui_story_5084_50840700_132_dialog_content = "เพื่อเชื่อฟังคำสั่งของเจ้าแห่งความจริง และแก้ไข\"จุดจบ\"ที่ถูกแสดงให้ฉันเห็น",
  ui_story_5084_50840700_133_dialog_content = "เธอก็กักตัวอยู่ในบ้านมานานแล้วนะ ที่สุดเธอเบื่อเรลิกแล้วหรือ?",
  ui_story_5084_50840700_134_dialog_content = "ตอนที่เราอายุเท่ากับนาย พ่อของนายและฉันได้ตื่นขึ้นพลังของสายเลือดของเรามานานแล้ว และหัวใจของเราไม่เคยพอใจในปัญญาของความจริง",
  ui_story_5084_50840700_135_dialog_content = "อาจจะเป็นเพราะคุณยังคงเป็นคนงมงายเหมือนเดิมหรือไม่? คุณยังไม่สามารถตอบคำถามของฉันเกี่ยวกับสัจธรรมได้หรือไม่?",
  ui_story_5084_50840700_136_dialog_content = "...ฉันได้ตัดสินใจที่จะเดินทางไปทั่วโลกเพื่อค้นหาความจริง",
  ui_story_5084_50840700_137_dialog_content = "ทำตามที่คุณชอบ",
  ui_story_5084_50840700_138_dialog_content = "และดังนั้นฉันได้เริ่มการเดินทางของฉัน และได้แสวงหาคำแนะนำจากสัจธรรมสำหรับตัวฉันเอง",
  ui_story_5084_50840700_139_dialog_content = "ในขณะที่ฉันเดินออกจากบ้าน ฉันเริ่มได้รับความรู้ที่ลึกซึ้งขึ้นเกี่ยวกับโลก",
  ui_story_5084_50840700_140_dialog_content = "และขณะที่ฉันเพิ่มความเข้าใจในความจริง พลังของเส้นเลือดของฉันก็เริ่มตื่นขึ้นอย่างทีละน้อย... แม้กระนั้นฉันยังปฏิเสธที่จะเข้าร่วมทรู ออเดอร์",
  ui_story_5084_50840700_141_dialog_content = "เมื่อฉันหาคำตอบที่เขาต้องการได้ในที่สุด ฉันก็กลับไปที่เมืองวารากิเพื่อบอกเขา... แต่กลับพบว่าเขาไม่ได้คาดหวังมันจากฉันอีกต่อไป",
  ui_story_5084_50840700_142_dialog_content = "Welcome back... You were gone for three months this time. How did you fare?",
  ui_story_5084_50840700_143_dialog_content = "... That's none of your concern.",
  ui_story_5084_50840700_144_dialog_content = "The look in your eyes... So full of resentment and uncertainty...",
  ui_story_5084_50840700_145_dialog_content = "What did you see in the outside world, Wilhelm Varaki?",
  ui_story_5084_50840700_146_dialog_content = "I don't recall letting you enter my room.",
  ui_story_5084_50840700_147_dialog_content = "You're the leader of the True Order, and yet you regularly leave without fulfilling your duties... You've been spending less time at home, as well.",
  ui_story_5084_50840700_148_dialog_content = "How many times must I tell you that it's none of your concern?! Now leave me!",
  ui_story_5084_50840700_149_dialog_content = "Very well then; I am no stranger to being denied your conversation. But given that tonight is the Advent of Truth, I was hoping we could have one final discussion.",
  ui_story_5084_50840700_150_dialog_content = "About The Truth, and ourselves...",
  ui_story_5084_50840700_151_dialog_content = "I said get out! Do not make me repeat myself!",
  ui_story_5084_50840700_152_dialog_content = "...",
  ui_story_5084_50840700_153_dialog_content = "ถึงตอนนี้ฉันก็ยังไม่เข้าใจเขาอยู่ดี",
  ui_story_5084_50840700_154_dialog_content = "ฉันกลัวว่าฉันอาจจะพลาดโอกาสสุดท้ายที่จะทำเช่นนั้นด้วย",
  ui_story_5084_50840700_155_dialog_content = "วิลเฮล์ม วารากิ: คุณลุงของฉันที่หยิ่งยโส น่ารังเกียจ และเข้าใจยาก... คนในครอบครัวที่ยังมีชีวิตอยู่... คุณไปที่ไหนมา?",
  ui_story_5084_50840700_156_dialog_content = "(เราเข้าใจแล้วว่าวิกตอเรียเห็นวิลเฮล์มในความทรงจำของเธออย่างไร...)",
  ui_story_5084_50840700_157_dialog_content = "(แต่จากมุมมองของวิลเฮล์ม เขาเสมอมาเป็นคนดูแลเธอ...)",
  ui_story_5084_50840700_158_dialog_content = "(เขาทนทุกข์จากการสูญเสียความควบคุมเอง และปฏิเสธที่จะดื่มเลือดของผู้ศรัทธาเหมือนกับหัวหน้าครอบครัวคนอื่น ๆ เขาคิดถึงผู้อื่นจนถึงสุดท้าย และยังสามารถช่วยเนลส์ได้...)",
  ui_story_5084_50840700_159_dialog_content = "(หลายปีที่ผ่านมา... พวกเขาไม่เคยเข้าใจกัน... แม้กระทั่งเวลเฮล์มถูกโจมตี...)",
  ui_story_5084_50840700_160_dialog_content = "(ฉันสงสัยว่าวิกตอเรียสามารถเห็นสิ่งที่ฉันเห็นได้หรือไม่...)",
  ui_story_5084_50840801_1_dialog_content = "เทียนเริ่มโหมกระพืออีกครั้ง—ครั้งนี้มันจะพาเราไปที่ไหนนะ?",
  ui_story_5084_50840801_2_dialog_content = "นี่คือวิกตอเรีย... และหัวหน้าครอบครัวที่เหลือ... ทุกคนทำอะไรอยู่ที่นี่?",
  ui_story_5084_50840801_3_dialog_content = "หืม? นั่นเฟาสต์ที่ยืนข้างๆ เธอเหรอ? และฉันคิดว่าเขากำลังมองเราอยู่นะ!",
  ui_story_5084_50840801_4_dialog_content = "นี่อาจจะเป็น...?",
  ui_story_5084_50840801_5_option_content = "เชื่อมโยงกระแสจิต",
  ui_story_5084_50840801_6_dialog_content = "เฟาสต์! ได้ยินเสียงฉันมั้ย?",
  ui_story_5084_50840801_7_dialog_content = "แน่นอน และฉันรู้ดีถึงความสงสัยที่คุณมีในตอนนี้",
  ui_story_5084_50840801_8_dialog_content = "คนที่คุณเห็นที่นี่คือคุณวิกตอเรีย คนที่คุณรู้จักดีเสมอ",
  ui_story_5084_50840801_9_dialog_content = "แต่ถ้าเป็นวิกตอเรียจากยุคของเรา... ทำไมเธอถึงยืนอยู่หน้าคนเหล่านี้...?",
  ui_story_5084_50840801_10_dialog_content = "วิลเฮล์มหายไปมาสามปีแล้ว ผู้สืบสันดานที่เหลือของวาราคีคือลูกของอิบราฮิมและวิกตอเรีย หลานสาวของวิลเฮล์ม",
  ui_story_5084_50840801_11_dialog_content = "(สามปี... วิลเฮล์มถูกโจมตีในปี 1915 ซึ่งหมายความว่าเราควรจะอยู่ในปี 1918 ตอนนี้ ใช่ไหม?)",
  ui_story_5084_50840801_12_dialog_content = "อย่างไรก็ตาม คลาวิส อิบราฮิมไม่ยินยอมให้ลูกของเขาเข้าร่วมทรู ออเดอร์ ซึ่งหมายความว่าเขาไม่มีสิทธิ์ในการนำทางออเดอร์นี้",
  ui_story_5084_50840801_13_dialog_content = "ตามที่เป็นอยู่ ตำแหน่งยังว่างอยู่และแหวนตระกูลก็หาไม่พบ พวกเราสงสัยว่ามันหายไปพร้อมกับวิลเฮล์ม วารากี้",
  ui_story_5084_50840801_14_dialog_content = "และตั้งแต่วิกตอเรียไม่มีสิทธิ์ในการรับมรดกความรู้จากบรรพบุรุษของเราอีกต่อไป...",
  ui_story_5084_50840801_15_dialog_content = "โอ้? พวกคุณทั้งหมดมาที่นี่วันนี้เพื่อแค่มาบอกฉันเรื่องนี้เหรอ?",
  ui_story_5084_50840801_16_dialog_content = "ฉันได้ยินว่าคุณชอบการแสวงหาความจริงโดยการเดินทางไปทั่วโลกภายนอก เราเคารพในการเลือกของคุณ",
  ui_story_5084_50840801_17_dialog_content = "คุณสามารถออกจากที่นี่ได้ หรือยังคงอยู่และเป็นส่วนหนึ่งของตระกูลพอร์ฟิริโอ ไม่ว่าจะเป็นอย่างไร คุณก็ไม่มีสิทธิ์นำทรู ออเดอร์ไปต่ออีกต่อไป",
  ui_story_5084_50840801_18_dialog_content = "ด้วยการมาถึงของความจริงที่จะเกิดขึ้นในคืนนี้ การนำทางของทรู ออเดอร์จะต้องล่มสลายไปยัง...",
  ui_story_5084_50840801_19_dialog_content = "การประชุมของทรู ออเดอร์ จริง ๆ แล้วกลายเป็นที่ว่างเปล่าและล่มสลายในยามที่วิลเฮล์มหายไปหรือ?",
  ui_story_5084_50840801_20_dialog_content = "แม้แต่ครอบครัวที่มีสายเลือดของเขาต้องจ่ายราคาที่สูงเกินควรสำหรับการดื่มเลือดที่ไม่ได้มีจุดประสงค์ให้บริโภค",
  ui_story_5084_50840801_21_dialog_content = "<color=#e8d9bb>วิกตอเรียเทแก้วไวน์สีเลือดลงบนโต๊ะหน้าหน้าเธอ ที่ด้านล่างของแก้วมีแหวนที่วิลเฮล์มเคยสวมอยู่</color>",
  ui_story_5084_50840801_22_dialog_content = "...?",
  ui_story_5084_50840801_23_dialog_content = "... แหวนของวิลเฮล์ม.",
  ui_story_5084_50840801_24_dialog_content = "เขามอบมันให้ฉันไม่นานก่อนที่จะออกจากที่นี่ คำพูดของบรรพบุรุษเราได้นำทางฉันมานานแล้ว",
  ui_story_5084_50840801_25_dialog_content = "ตอนนี้บอกฉันสิ, นายมีอะไรจะพูดเพิ่มเติมเกี่ยวกับการนำทางของทรู ออเดอร์ไหม?",
  ui_story_5084_50840801_26_dialog_content = "เป็นไปไม่ได้!",
  ui_story_5084_50840801_27_dialog_content = "ต้องเปลี่ยนแผนแล้ว...",
  ui_story_5084_50840801_28_dialog_content = "ดูเหมือนว่าทุกคนในหมู่คุณมีแผนการที่รู้จักบางอย่าง",
  ui_story_5084_50840801_29_dialog_content = "นี่คือความรู้ที่ถูกเปิดเผยให้ฉันรู้ในช่วงการมาถึงของความจริง สามปีที่แล้ว",
  ui_story_5084_50840801_30_dialog_content = "สามปีที่ผ่านมา...",
  ui_story_5084_50840801_31_dialog_content = "ไม่, นี่ไม่ได้!",
  ui_story_5084_50840801_32_dialog_content = "Still counting on others, Porfirio? Your end is near, and no one will save you from it!",
  ui_story_5084_50840801_33_dialog_content = "You remember our deal... Don't you?",
  ui_story_5084_50840801_34_dialog_content = "...",
  ui_story_5084_50840801_35_dialog_content = "<size=45>อา-!!!</size>",
  ui_story_5084_50840801_36_dialog_content = "ถูกลงโทษให้ต้องตายอย่างไม่เกียรติในเมืองบ้านเกิดของตัวเอง... ฉันสงสารเจ้า Wilhelm Varaki.",
  ui_story_5084_50840801_37_dialog_content = "...",
  ui_story_5084_50840801_38_dialog_content = "และไม่มีทายาทที่จะพูดถึง แหวนของวารากี้ก็สูญหายความหมายทั้งหมด",
