  ui_story_5084_50841102_22_dialog_content = "คุณต้องการสารภาพอะไรกับเจ้าแห่งความจริงหรือไม่?",
  ui_story_5084_50841102_23_dialog_content = "ฉันขอสารภาพ... ว่าฉันได้กระทำบาปตั้งแต่วินาทีแรกที่ฉันเกิดมา ดูด้วยตัวคุณเองสิ ท่านผู้คุม...",
