  ui_story_5084_50841302_68_dialog_content = "ความสามารถในการสื่อสารทางจิตของ Caelestite จริงๆ แล้วมีสิ่งที่ร่วมกันกับพลังงานที่แวมไพร์ระดับสูงครอบครอง และพลังงานนั้นเองก็เป็นรากฐานสำหรับ Aurorians ทั้งหมด",
  ui_story_5084_50841302_69_dialog_content = "แม่น้ำที่สะอาดสวยงาม?",
