  ui_story_5084_50841302_72_dialog_content = "แต่แม่น้ำปริสุทธิ์ที่อยู่เบื้องหลังของม้วนภาพโบราณ ดูเหมือนจะมีคนมาเยี่ยมชมแล้ว",
  ui_story_5084_50841302_73_dialog_content = "ฉันจะไปหาที่ที่กล่าวมา ดังนั้นฉันขอมอบเมืองนี้ให้กับทุกคนของพวกคุณ",
