  ui_story_5084_50841302_92_dialog_content = "อาจจะเป็นเพราะพี่ชายของฉันไว้วางใจหนังสือเล่มนี้ให้กับคุณ เพื่อนสนิทของเขา ด้วยความตั้งใจที่จะให้ฉันเอามันไปเมื่อถึงเวลาที่เหมาะสม",
