  ui_story_5084_50841400_55_dialog_content = "<color=#e8d9bb>\"วิกตอเรียตัวน้อยเปิดตำราเปล่าและได้ยินคำทำนายเกี่ยวกับ 'สัจธรรม' เป็นครั้งแรก\"</color>",
  ui_story_5084_50841400_56_dialog_content = "<color=#e8d9bb>หนังสือนั้นยังคงไหลลงไปตามกระแสน้ำ ในสายน้ำแห่งเวลานั้นไม่มีจุดเริ่มต้นหรือจุดสิ้นสุด แต่เป็นวัฏจักรที่ไม่รู้จบ</color>",
  ui_story_5084_50841400_57_dialog_content = "<color=#e8d9bb>\"ดังนั้น, วิกตอเรียจึงปล่อยไบเบิลที่ได้รับความรักเคารพจากเธอมาหลายปี และมองมันลอยไปในน้ำหลาก\"</color>",
  ui_story_5084_50841400_58_dialog_content = "นักเดินทางทั้งหมดได้กลับไปยังเวลาของตนเองแล้ว ฉันควรจะทำงานเสร็จสิ้นด้วย",
  ui_story_5084_50841400_59_dialog_content = "วิกตอเรียของปี 1918, คุณยังคงอยู่บนเส้นทางในการค้นหาความจริง คุณยังคงหลงทางและทุกสิ่งทุกอย่างต้องดูสับสนสำหรับคุณ",
  ui_story_5084_50841400_60_dialog_content = "นั่นก็ไม่เป็นไร ครั้งหนึ่งเวลาจะนำคุณไปสู่มัน",
  ui_story_5084_50841400_61_dialog_content = "คุณจะต้องเริ่มการเดินทางที่ยาวนานก่อนที่จะได้รับการรู้แจ้ง",
  ui_story_5084_50841400_62_dialog_content = "แล้วคุณจะนำพวกเขากลับมาที่จุดนี้ และเราจะพบกันอีกครั้ง",
  ui_story_5084_50841400_63_dialog_content = "<color=#e8d9bb>วิลเฮล์มส่งวิกตอเรียที่หลับไปในวอร์เท็กซ์ให้เธอและวางไบเบิลโชกเลือดลงไปในมือเธอ</color>",
  ui_story_5084_50841400_64_dialog_content = "<color=#e8d9bb>เขาจึงนอนลงในโลงศพที่เขามา และครุ่นคิดเรื่องอดีตของตน</color>",
  ui_story_5084_50841400_65_dialog_content = "เมื่อคุณยังเป็นเด็ก พบฉันครั้งแรก เนื่องจากพี่ชายของคุณต้องการที่จะมอบคุณให้ฉัน เพราะเขากำลังจะตาย",
  ui_story_5084_50841400_66_dialog_content = "เพื่อให้ฉันเป็นผู้นำเหรอ",
  ui_story_5084_50841400_67_dialog_content = "ใช่ แล้วก็ดูแลคุณวิกตอเรียด้วยนะ",
  ui_story_5084_50841400_68_dialog_content = "<color=#e8d9bb>วิกตอเรียยืนอยู่อย่างเงียบงันข้างๆ พ่อแม่ของเธอ ไม่เข้าใจเหตุผลที่พวกเขายินดี แม้ว่าพวกเขาจะกำลังจะตาย</color>",
  ui_story_5084_50841400_69_dialog_content = "<color=#e8d9bb>แต่วิลเฮล์ม วารากิ ผู้ที่ทนทุกข์ทรมานอย่างไม่รู้จบ ไม่สามารถทนทานได้ที่จะนำวิกตอเรียที่พังทลายลงสู่ทางที่ราชันย์แห่งชะตาของแวมไพร์</color>",
  ui_story_5084_50841400_70_dialog_content = "หยุดเสียเวลาเถอะ ฉันจะไม่ทำมัน",
  ui_story_5084_50841400_71_dialog_content = "...",
  ui_story_5084_50841400_72_dialog_content = "<color=#e8d9bb>แต่ในวันงานศพ วิลเฮล์มยังคงสวมชุดของลูกศิษย์และมองดูพี่ชายและน้องสาวของเขาออกจากเมืองวารากิในโลงศพ</color>",
  ui_story_5084_50841400_73_dialog_content = "<color=#e8d9bb>วิลเฮล์มยังคงอยู่นอกหลุมฝังศพวารากิ ฟังการ \"ทักทาย\" จากผู้บังคับบัญชาสำหรับวิกตอเรีย</color>",
  ui_story_5084_50841400_74_dialog_content = "<color=#e8d9bb>พลังของพายุและสายฟ้าที่ดูเหมือนจะฉีกโลกออกจากกัน สะท้อนถึงอารมณ์ของวิลเฮล์ม</color>",
  ui_story_5084_50841400_75_dialog_content = "<color=#e8d9bb>เขาวิ่งเข้าสู่หัวใจของสุสานเพื่อสวมแหวนวาราคีที่สามารถทำให้เขาเสื่อมโทรมได้ ต่อหน้าคณะผู้บริหาร...</color>",
  ui_story_5084_50841400_76_dialog_content = "<color=#e8d9bb>เพียงเพื่อปกป้องเด็กหญิงที่กำลังจะเริ่มต้นการตามหาความจริงด้วยเขา</color>",
  ui_story_5084_50841400_77_dialog_content = "<color=#e8d9bb>แม้ว่าความสัมพันธ์ระหว่างพวกเขาจะไม่มีความสุข แต่วิลเฮล์มต้องบังคับวิกตอเรียให้หยุดต่อต้านออเดอร์และเพิ่มพลังขึ้น</color>",
  ui_story_5084_50841400_78_dialog_content = "<color=#e8d9bb>ตลอดเวลาที่กำลังค้นหาทางเลือกใด ๆ เพื่อรักษาความปลอดภัยของพวกเขา</color>",
  ui_story_5084_50841400_79_dialog_content = "<color=#e8d9bb>เกี่ยวกับความตายของเขาเองด้วย...</color>",
  ui_story_5084_50841400_80_dialog_content = "Cleves...",
  ui_story_5084_50841400_81_dialog_content = "I know you'll understand from caring for Victoria.",
  ui_story_5084_50841400_82_dialog_content = "คุณวิกตอเรีย...",
  ui_story_5084_50841400_83_dialog_content = "หึหึ...",
  ui_story_5084_50841400_84_dialog_content = "(ตามประเพณีของแวมไพร์ ความตายอาจเป็นพระคุณอย่างหนึ่ง)",
  ui_story_5084_50841400_85_dialog_content = "(แต่ตัวฉันคนนี้ไม่รู้สึกเจ็บปวดจากการทรยศของคนอื่นอีกต่อไป)",
  ui_story_5084_50841400_86_dialog_content = "(ฉันเข้าใจว่ามันยากขนาดไหนสำหรับคุณ แต่วิกตอเรียจะกลายเป็นอย่างไรต่อไปนี้ล่ะ?)",
  ui_story_5084_50841400_87_dialog_content = "(ฉันได้ส่งผ่านความจริงทุกอย่างที่ฉันเรียนรู้ให้เธอหรือไม่?)",
  ui_story_5084_50841400_88_dialog_content = "(เธอกำลังจะบอกฉันว่าเธอกำลังเดินทางอย่างไม่ไหว้วาวในทางสู่ความจริงก่อนที่เธอจะออกไปหรือเปล่า?)",
  ui_story_5084_50841400_89_dialog_content = "(...)",
  ui_story_5084_50841400_90_dialog_content = "<color=#e8d9bb>วิลเฮล์มไม่เคยหยุดถามถึงความจริงเมื่อใจของเขาเปลี่ยนไปสู่แม่น้ำที่ใส</color>",
  ui_story_5084_50841400_91_dialog_content = "อะไรเกิดขึ้น? ฉันไม่ได้อยู่ที่โบสถ์หรอ...? ตอนนี้ฉันควรจะตายไปแล้ว.",
  ui_story_5084_50841400_92_dialog_content = "แล้วฉันอยู่ที่ไหนเนี่ย?",
  ui_story_5084_50841400_93_dialog_content = "แดนแห่งความตาย หรือวัดของเจ้าพระยาแห่งความจริง?",
  ui_story_5084_50841400_94_dialog_content = "แม่น้ำนี้คืออะไร?",
  ui_story_5084_50841400_95_dialog_content = "<color=#e8d9bb>วิลเฮล์มล่องลอยไปอย่างไม่มีที่สิ้นสุดโดยไม่เคลื่อนไหว แต่จิตใจของเขารับรู้ข้อมูลทั้งหมดในโลก</color>",
  ui_story_5084_50841400_96_dialog_content = "<color=#e8d9bb>หนึ่งทศวรรษ? หนึ่งศตวรรษ? มันนานแค่ไหนแล้ว...?</color>",
  ui_story_5084_50841400_97_dialog_content = "<color=#e8d9bb>Eoria มืดลงและสว่างขึ้นอีกครั้ง ขณะที่ความขัดแย้งระหว่าง Aurorians และ Eclipsites ยังคงลุกลาม</color>",
  ui_story_5084_50841400_98_dialog_content = "<color=#e8d9bb>แต่เขาก็ลอยผ่านทุกสิ่งทุกอย่าง</color>",
  ui_story_5084_50841400_99_dialog_content = "นั่นฉันหรือ?",
  ui_story_5084_50841400_100_dialog_content = "นั่นไม่ใช่ความปรารถนาของเธอ แต่มันคือโชคชะตาของเธอ ใส่ไบเบิลโชกเลือดใหม่นี้ลงในโลงศพให้ฉัน เธอจะพบว่ามันมีประโยชน์",
  ui_story_5084_50841400_101_dialog_content = "ใช่ คุณวิลเฮล์ม!",
  ui_story_5084_50841400_102_dialog_content = "และเมื่อถึงเวลานั้น...",
  ui_story_5084_50841400_103_dialog_content = "ทำไมคุณถึงเศร้า? คุณสามารถเริ่มต้นครอบครัวแล้วจบเรื่องได้เลย",
  ui_story_5084_50841400_104_dialog_content = "เริ่มต้นครอบครัวและเลี้ยงลูกเล็กเด็กแดง? น่าเบื่อจริง ๆ",
  ui_story_5084_50841400_105_dialog_content = "<color=#e8d9bb>มีเวอร์ชั่นของวิลเฮล์มหลายๆ อยู่ทั่วทุกที่ แต่ก็ซ้อนกันอยู่ มันเป็นความสับสนอย่างบริสุทธิ์จนกระทั่งเขาเห็นความมีอยู่ที่ไม่ใช่ตัวเขาเอง</color>",
  ui_story_5084_50841400_106_dialog_content = "ฉันจะไม่รับเครดิตสำหรับมัน นี่เป็นพรจากเจ้าแห่งความจริง",
  ui_story_5084_50841400_107_dialog_content = "อะไรเนี่ย",
  ui_story_5084_50841400_108_dialog_content = "<color=#FFB400>แม่น้ำพริสทีน</color> นอกเหนือจากเวลาและพื้นที่ ความแตกต่างเดียวจากโลกภายนอกคือมันไหลเวียน",
  ui_story_5084_50841400_109_dialog_content = "ถ้าเป็นแบบนี้ต่อไป เราจะไม่สามารถควบคุมชีวิตของเราได้! ทำไมคุณถึงพาเรามาที่นี่?",
  ui_story_5084_50841400_110_dialog_content = "วิกตอเรีย?!",
  ui_story_5084_50841400_111_dialog_content = "ฮิ, ฮ่าฮ่าฮ่า!",
  ui_story_5084_50841400_112_dialog_content = "ฉันรู้อยู่แล้วว่าคุณทำได้ วิกตอเรีย วาราคี",
  ui_story_5084_50841400_113_dialog_content = "และคารอนก็เช่นกัน",
  ui_story_5084_50841400_114_dialog_content = "เราทำมันได้ในฐานะผู้สูงอายุของพวกเขา, Cleves.",
  ui_story_5084_50841400_115_dialog_content = "<color=#e8d9bb>เมื่อความทรงจำเริ่มจางหาย วิลเฮล์มลุกขึ้นเพื่อตระหนักว่าเขาไม่ได้อยู่ในโลงศพของเขา—แต่กำลังมองและหลงสู่แม่น้ำพริสทีนที่ไหลอย่างไม่รู้จบ</color>",
  ui_story_5084_50841400_116_dialog_content = "<color=#e8d9bb>ทุกสิ่งที่เขาได้แทรกแซงจะทำให้เขาต้องเผชิญหน้ากับการยืนยันความจริง</color>",
  ui_story_5084_50841400_117_dialog_content = "<color=#e8d9bb>แล้ว...</color>",
  ui_story_5084_50841400_118_dialog_content = "<color=#e8d9bb>ตำราที่วิกตอเรียทิ้งไว้หยุดลอยเพราะมันปะทะกับอุปสรรค - คือ \"คนตาย\" ที่นอนอยู่ในแม่น้ำ</color>",
  ui_story_5084_50841400_119_dialog_content = "<color=#e8d9bb>ร่างของวิลเฮล์มผู้ถูกทรยศ ผู้ที่ประตูแห่งชะตาชีวิตเรียกหา ได้ตื่นขึ้นในกระแสที่น่าทึ่ง</color>",
  ui_story_5084_50841400_120_dialog_content = "...?!",
  ui_story_5084_50841400_121_dialog_content = "<color=#e8d9bb>วิลเฮล์มที่สับสนก็สามารถสังเกตเห็นไบเบิลโชกเลือดที่หยุดอยู่ที่เท้าของเขาในแม่น้ำ</color>",
  ui_story_5084_50841400_122_dialog_content = "<color=#e8d9bb>เหมือนกับการตอบสนองการเรียกเงียบ ๆ ของใครสักคน เขาเริ่มพลิกหนังสือที่เป็นหน้าว่างทั้งหมดและเริ่มเห็น...</color>",
  ui_story_5084_50841400_123_dialog_content = "<color=#e8d9bb>\"ไบเบิลโชกเลือดลอยไปแล้วหยุดอยู่ข้างเท้าของวิลเฮล์มที่ตายไปแล้ว แวมไพร์หนุ่มตื่นขึ้นเนื่องจากหยดเลือดในซากแหวน.\"</color>",
  ui_story_5084_50841400_124_dialog_content = "<color=#e8d9bb>\"วิลเฮล์มที่งงงวยสามารถสังเกตเห็นไบเบิลโชกเลือดที่หยุดอยู่ที่เท้าของเขาในแม่น้ำ\"</color>",
  ui_story_5084_50841400_125_dialog_content = "ว่าไง",
  ui_story_5084_50841400_126_dialog_content = "<color=#e8d9bb>\"วิลเฮล์มตกใจจนสะดุดกลับหลังลงแม่น้ำ โดยทำให้ตัวเองเปียกสุกในน้ำที่เขาได้รบกวน และทำให้สาเหตุและผลกระทบเกิดความเสียหาย.\"</color>",
  ui_story_5084_50841400_127_dialog_content = "<color=#e8d9bb>\"วิลเฮล์มนั่งอยู่ในแม่น้ำ แล้วเขาสังเกตว่ามีอะไรอยู่ในมือเขา เมื่อเขาหยิบมันขึ้นมาในขณะที่รู้สึกหนาวเข้า เขาก็รู้ว่ามันคือ...\"</color>",
  ui_story_5084_50841400_128_dialog_content = "แหวนของบรรพบุรุษวาราคีหรือ?",
  ui_story_5084_50841400_129_dialog_content = "นี่ทั้งหมดหมายความว่าอย่างไร?",
  ui_story_5084_50841400_130_dialog_content = "<color=#e8d9bb>\"วิลเฮล์มที่ได้รับการเรียกเชิญ จะถูกนำไปสู่การล่องลอยและนำคนอื่น ๆ ไปสู่ 'ความจริง'.\"</color>",
  ui_story_5084_50841400_131_dialog_content = "<color=#e8d9bb>\"เมื่อถึงเวลาที่เหมาะสม สุสานวาราคีจะเปิดตัวสำหรับวิกตอเรีย วิลเฮล์ม คนรับใช้แห่งความจริง จะเป็นผู้นำทางสำหรับเธอ\"</color>",
  ui_story_5084_50841400_132_dialog_content = "<color=#e8d9bb>\"วิลเฮล์มจึงนอนลงในโลงศพที่เขามาพร้อมกับ และครุ่นคิดเรื่องอดีตของเขา\"</color>",
  ui_story_5084_50841400_133_dialog_content = "<color=#e8d9bb>\"เมื่อเขาตระหนักว่าจุดประสงค์ของเขาได้รับการบรรลุและวิกตอเรียพร้อมแล้ว จะเขาจะสามารถพักผ่อนอย่างสงบได้ในที่สุดหรือไม่?\"</color>",
  ui_story_5084_50841400_134_dialog_content = "<color=#e8d9bb>\"แต่เมื่อเขาสัมผัสแหวน หยดเลือดของวารากิที่อยู่ในนั้นไหลผ่านร่างกายเขา เขาตกลงไปในความหลับในขณะที่ความรู้สึกที่คุ้นเคยกลับมาอีกครั้ง\"</color>",
  ui_story_5084_50841400_135_dialog_content = "<color=#e8d9bb>\"เมื่อวิลเฮล์มตื่นขึ้นอีกครั้ง พระองค์จะถูกนำไปสู่ทางแยกแห่งโชคชะตา\"</color>",
  ui_story_5084_50841400_136_dialog_content = "ฉันอยู่ที่ไหน...",
  ui_story_5084_50841400_137_dialog_content = "ถึงแม้ท่านหญิงวิกตอเรียจะบอกฉันว่าความเลื่อมใสจะแสดงทางให้ฉัน...",
  ui_story_5084_50841400_138_dialog_content = "แต่ฉันจะเสียสละ...",
  ui_story_5084_50841400_139_dialog_content = "I will...",
  ui_story_5084_50841400_140_dialog_content = "...",
  ui_story_5084_50841400_141_dialog_content = "... My lord?",
  ui_story_5084_50841400_142_dialog_content = "เจ้าแห่งสัจธรรมที่ยิ่งใหญ่!",
  ui_story_5084_50841400_143_dialog_content = "Did you just say... Lady Victoria?",
